// tile_uniq_rids个unique row indices

Reuse_Din_Rows = {
    Inter-tile: 0
        // 上一tile已将此dense row集加载到FLM, 当前tile直接复用
        // 适用: scratchpad-based Dout, tiled traversal中的non-first tile
    Intra-tile (stream): tile_width
        // 执行前将整个tile宽度的dense rows stream到scratchpad
        // 适用: scratchpad-based Din, tiled traversal (如Sextans)
    Intra-tile (demand): tile_uniq_cids
