        // 适用: on-demand access, 不存在FLM, nonzeros间距大无法cache复用
}

Reuse_Dout_Rows = {
    Inter-tile: 0 
        // 适用: scratchpad-based Dout复用, 或tiled traversal中已load过
    Intra-tile (stream): tile_height
        // 适用: scratchpad-based Dout, streaming整个tile高度(如tiled traversal首tile)
    Intra-tile (demand): tile_uniq_rids
        // 适用: on-demand, row-ordered traversal: same r_id nonzeros共享Dout行
